    vector<vector<long long>> meetings(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> meetings[i][j];
        }
    }

    sort(meetings.begin(), meetings.end());
    long long prevEnd = 0;
    bool ok = true;
    for (const vector<long long>& m : meetings) {
        if (m[0] < prevEnd) { ok = false; break; }
        prevEnd = m[1];
    }
    cout << (ok ? "yes" : "no") << "\n";

